import pyomo.environ as pyo

DATA = {
    "foods": ["Eggs", "Grains", "Berries", "Nuts",
              "Salmon", "Vegetables", "Rice", "Meat"],
    "nutrients": ["protein", "carbs", "calories"],
    # cost per serving
    "cost": {
        "Eggs": 4, "Grains": 3, "Berries": 2, "Nuts": 4,
        "Salmon": 9, "Vegetables": 3, "Rice": 6, "Meat": 6,
    },
    # nutrient content per serving
    "protein": {
        "Eggs": 2, "Grains": 7, "Berries": 6, "Nuts": 16,
        "Salmon": 20, "Vegetables": 6, "Rice": 6, "Meat": 5,
    },
    "carbs": {
        "Eggs": 4, "Grains": 9, "Berries": 18, "Nuts": 3,
        "Salmon": 11, "Vegetables": 27, "Rice": 30, "Meat": 1,
    },
    "calories": {
        "Eggs": 282, "Grains": 104, "Berries": 71, "Nuts": 116,
        "Salmon": 175, "Vegetables": 132, "Rice": 251, "Meat": 74,
    },
    # minimum daily requirements
    "req_protein": 84,
    "req_carbs": 195,
    "req_calories": 1941,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.I = pyo.Set(initialize=d["foods"])

    model.servings = pyo.Var(model.I, within=pyo.NonNegativeReals, bounds=(0, None))

    def obj_rule(m):
        return sum(d["cost"][i] * m.servings[i] for i in m.I)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def protein_rule(m):
        return sum(d["protein"][i] * m.servings[i] for i in m.I) >= d["req_protein"]

    model.protein_req = pyo.Constraint(rule=protein_rule)

    def carbs_rule(m):
        return sum(d["carbs"][i] * m.servings[i] for i in m.I) >= d["req_carbs"]

    model.carbs_req = pyo.Constraint(rule=carbs_rule)

    def calories_rule(m):
        return sum(d["calories"][i] * m.servings[i] for i in m.I) >= d["req_calories"]

    model.calories_req = pyo.Constraint(rule=calories_rule)

    return model


